<template>
  <section class="report-renderer" :class="[`layout-${resolvedTemplate.layout}`, `device-${device}`]" :style="themeStyle">
    <div class="report-device-frame">
      <header v-if="resolvedTemplate.displayOptions?.studentInfo !== false" class="report-topbar"><span class="report-brand">AI创意美术</span><span>{{ studentName }} · {{ editionLabel }}</span></header>
      <H5LayoutPage v-if="layoutSnapshot?.pages?.length" :page="activePage" :page-number="`${currentIndex + 1} / ${normalizedPages.length}`" />
      <ProductStoryPage v-else-if="isProductStory" :page="activePage" :index="currentIndex" :total="normalizedPages.length" :student-name="studentName" @comment="$emit('comment')" @like="$emit('like')" />
      <article v-else class="report-page"><div class="report-copy"><span>{{ activePage.eyebrow || activePage.label || '我的创作报告' }}</span><h2>{{ activePage.title || '我的创作故事' }}</h2><p>{{ activePage.text || activePage.body || '这一页正在等待我补充创作内容。' }}</p><small>{{ currentIndex + 1 }} / {{ normalizedPages.length }}</small></div><div v-if="activePage.src" class="report-art" :style="imageStyle(activePage.src)"></div><div v-else class="report-empty">还没有可展示的素材</div></article>
      <nav v-if="resolvedTemplate.displayOptions?.chapterNav !== false && normalizedPages.length > 1" class="report-nav" aria-label="H5报告章节"><button type="button" :disabled="currentIndex === 0" aria-label="上一页" @click="go(-1)">‹</button><button v-for="(page, index) in normalizedPages" :key="page.id || index" type="button" :class="{ active: currentIndex === index }" @click="setPage(index)"><span>{{ page.label || page.title || `第${index + 1}页` }}</span></button><button type="button" :disabled="currentIndex === normalizedPages.length - 1" aria-label="下一页" @click="go(1)">›</button></nav>
      <footer v-if="layoutSnapshot?.pages?.length && resolvedTemplate.officialUrl" class="report-actions"><button type="button" @click="$emit('official')">进入官网</button></footer>
      <footer v-else-if="showActions && !layoutSnapshot" class="report-actions"><button v-if="resolvedTemplate.displayOptions?.social !== false" type="button" @click="$emit('like')">点赞</button><button v-if="resolvedTemplate.displayOptions?.social !== false" type="button" @click="$emit('comment')">评语</button><button v-if="resolvedTemplate.displayOptions?.download !== false" type="button" @click="$emit('download')">下载</button></footer>
    </div>
  </section>
</template>

<script setup>
import { computed, defineComponent, h, ref, watch } from 'vue'
import H5LayoutPage from './H5LayoutPage.vue'

const props = defineProps({ template: { type: Object, default: () => ({}) }, layoutSnapshot: { type: Object, default: null }, pages: { type: Array, default: () => [] }, device: { type: String, default: 'tablet' }, studentName: { type: String, default: '林同学' }, editionLabel: { type: String, default: '入门版' }, modelValue: { type: Number, default: 0 }, showActions: { type: Boolean, default: false } })
const emit = defineEmits(['update:modelValue', 'like', 'comment', 'download', 'official'])
const internalIndex = ref(props.modelValue)
const resolvedTemplate = computed(() => ({ layout: 'kids-classroom', theme: { primary: '#1677ff', secondary: '#20c7d9', accent: '#ff9518', background: '#f5f9ff', surface: '#ffffff', text: '#17315f' }, displayOptions: { studentInfo: true, chapterNav: true, social: true, download: true, official: true }, ...props.template, theme: { primary: '#1677ff', secondary: '#20c7d9', accent: '#ff9518', background: '#f5f9ff', surface: '#ffffff', text: '#17315f', ...(props.template?.theme || {}) } }))
const normalizedPages = computed(() => props.layoutSnapshot?.pages?.length ? props.layoutSnapshot.pages : props.pages.length ? props.pages : [{ id: 'cover', type: 'cover', label: '封面', title: '我的创作故事', text: '这是我认真完成的作品。' }])
const currentIndex = computed(() => Math.min(internalIndex.value, Math.max(normalizedPages.value.length - 1, 0)))
const activePage = computed(() => normalizedPages.value[currentIndex.value] || normalizedPages.value[0] || {})
const isProductStory = computed(() => resolvedTemplate.value.layout === 'product-design-story')
const themeStyle = computed(() => ({ '--report-primary': resolvedTemplate.value.theme.primary, '--report-secondary': resolvedTemplate.value.theme.secondary, '--report-accent': resolvedTemplate.value.theme.accent, '--report-bg': resolvedTemplate.value.theme.background, '--report-surface': resolvedTemplate.value.theme.surface, '--report-text': resolvedTemplate.value.theme.text, fontFamily: resolvedTemplate.value.fontFamily || 'Microsoft YaHei' }))
watch(() => props.modelValue, value => { internalIndex.value = Number(value) || 0 })
function setPage(index) { internalIndex.value = Math.min(Math.max(index, 0), Math.max(normalizedPages.value.length - 1, 0)); emit('update:modelValue', internalIndex.value) }
function go(direction) { setPage(currentIndex.value + direction) }
function styleFor(src) {
  if (!src) return { background: 'linear-gradient(145deg, #dff1ff, #eff5ff)' }
  return String(src).startsWith('linear-gradient') ? { background: src } : { backgroundImage: `url("${src}")` }
}
const imageStyle = styleFor

const ProductStoryPage = defineComponent({
  props: { page: Object, index: Number, total: Number, studentName: String }, emits: ['comment', 'like'],
  setup(componentProps, { emit: componentEmit }) {
    const images = computed(() => [...new Set([componentProps.page?.src, ...(componentProps.page?.images || [])].filter(Boolean))].slice(0, 3))
    const bg = src => styleFor(src)
    return () => {
      const p = componentProps.page || {}; const step = p.storyStep || 'cover'; const media = images.value
      const header = h('header', { class: 'story-heading' }, [h('span', p.eyebrow || '我的产品设计故事'), h('b', `${componentProps.index + 1} / ${componentProps.total}`)])
      const copy = h('div', { class: 'story-copy' }, [h('h2', p.title || p.label || '我的创作故事'), h('p', p.text || '我正在补充这一段创作故事。')])
      const avatar = h('div', { class: ['story-avatar', `pose-${p.character?.pose || 'presenting'}`] }, [h('span', '我'), h('i')])
      let body
      if (step === 'cover') body = [h('div', { class: 'story-cover-copy' }, [h('p', `大家好，我是 ${componentProps.studentName}`), h('h2', p.title), h('span', p.narration?.highlight)]), h('div', { class: ['story-cover-hero', { 'is-empty': !media[0] }], style: bg(media[0]) }, media[0] ? [] : [h('div', { class: 'story-missing-media' }, [h('b', '我的最终作品还在准备中'), h('span', '完成一张作品或选择一张AI方案后，这里会展示我的真实设计。')])]), media[1] && h('div', { class: 'story-cover-detail', style: bg(media[1]) })]
      else if (step === 'inspiration') body = [copy, h('div', { class: 'story-inspiration-board' }, media.map((src, i) => h('div', { class: `inspiration-card card-${i}`, style: bg(src) }, i === 0 ? [h('small', '我的观察')] : []))), h('em', { class: 'story-quote' }, `“${p.narration?.highlight || ''}”`)]
      else if (step === 'problem') body = [copy, h('div', { class: 'story-problem-layout' }, [h('div', { class: 'story-problem-image', style: bg(media[0]) }), h('div', { class: 'story-problem-cards' }, (p.cards || []).map((card, i) => h('span', [h('b', `0${i + 1}`), card])))])]
      else if (step === 'sketch') body = [copy, h('div', { class: 'story-sketch-compare' }, [h('div', { style: bg(media[0]) }, [h('small', '最初草图')]), h('i', '→'), h('div', { style: bg(media[1] || media[0]) }, [h('small', '修改后')])]), h('em', { class: 'story-hand-note' }, p.narration?.highlight || '')]
      else if (step === 'ai') body = [copy, h('div', { class: 'story-ai-grid' }, media.map((src, i) => h('div', { class: { selected: i === 0 }, style: bg(src) }, [h('small', ['方案 A', '我选择了它', '方案 C'][i])]))), h('div', { class: 'story-choice-row' }, (p.cards || []).map(card => h('span', card)))]
      else if (step === 'model') body = [copy, h('div', { class: 'story-model-hero', style: bg(media[0]) }, [h('i', media[0] ? '3D / 结构' : '结构与制作思考')]), h('div', { class: 'story-model-details' }, media.slice(1).map(src => h('span', { style: bg(src) })))]
      else if (step === 'scene') body = [h('div', { class: 'story-scene-backdrop', style: bg(media[0]) }), h('div', { class: 'story-scene-copy' }, [h('h2', p.title), h('p', p.text), h('b', p.narration?.highlight)]), media[1] && h('div', { class: 'story-scene-product', style: bg(media[1]) })]
      else body = [copy, h('div', { class: ['story-reflection-hero', { 'is-empty': !media[0] }], style: bg(media[0]) }, media[0] ? [] : [h('div', { class: 'story-missing-media' }, [h('b', '我的最终作品还在完善中'), h('span', '完成作品后，这里会展示它和我的创作时间线。')])]), h('div', { class: 'story-reflection-row' }, (p.cards || []).map(card => h('span', card))), h('div', { class: 'story-action-row' }, [p.videoSrc && h('button', '视频讲解'), h('button', { onClick: () => componentEmit('comment') }, '讲师评语'), h('button', { onClick: () => componentEmit('like') }, '点赞分享')])]
      return h('article', { class: ['story-page', `story-${step}`, `story-layout-${p.layoutVariant || ''}`, `story-background-${p.backgroundStyle || ''}`] }, [h('div', { class: 'story-blueprint' }), header, ...body.filter(Boolean), avatar])
    }
  },
})
</script>

